  Lemma sc_disj : forall M E (sa1 sa2 : saddr) (b1 b2 n1 n2 : Z),
    edenot E (a_base sa1) = Z_to_bv 64 b1 -> edenot E (a_base sa2) = Z_to_bv 64 b2 ->
