    0 < n1 < 2 ^ 64 -> 0 < n2 < 2 ^ 64 ->
    (b1 + a_off sa1 + n1 <= b2 + a_off sa2 \/ b2 + a_off sa2 + n2 <= b1 + a_off sa1) ->
    sc_denot SEGS M E (SCDisj sa1 (ELit n1) sa2 (ELit n2)).
